import React from 'react';

export default function ListOfPlayers() {
  const players = [
    { name: 'Jack', score: 50 },
    { name: 'Michael', score: 70 },
    { name: 'John', score: 40 },
    { name: 'Ann', score: 61 },
    { name: 'Elisabeth', score: 61 },
    { name: 'Sachin', score: 95 },
    { name: 'Dhoni', score: 100 },
    { name: 'Virat', score: 84 },
    { name: 'Jadeja', score: 64 },
    { name: 'Raina', score: 75 },
    { name: 'Rohit', score: 80 },
  ];

  const playersBelow70 = players.filter((p) => p.score < 70);

  return (
    <div>
      <h1>List of Players</h1>
      <ul>
        {players.map((item, i) => (
          <li key={i}>Mr. {item.name} <span>{item.score}</span></li>
        ))}
      </ul>
      <hr />
      <h1>List of Players having Scores Less than 70</h1>
      <ul>
        {playersBelow70.map((item, i) => (
          <li key={i}>Mr. {item.name} <span>{item.score}</span></li>
        ))}
      </ul>
    </div>
  );
}
